            try { $stderr = (Get-Content -LiteralPath $errFile -Raw -ErrorAction SilentlyContinue).Trim() } catch { $stderr = '' }
            if([string]::IsNullOrWhiteSpace($stdout)){ return $false }
            if($stderr -match '(?i)failed to connect|daemon is not running|error during connect|cannot find'){ return $false }
            return $true
        } catch {
