    function Save-RedockerSafeText {
        param([string]$Path,[string]$Text)
        $parent = Split-Path -Parent $Path
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
        $temporary = Join-Path $parent ('.' + [IO.Path]::GetFileName($Path) + '.' + [guid]::NewGuid().ToString('N') + '.tmp')
        try {
            [IO.File]::WriteAllText($temporary,$Text,[Text.UTF8Encoding]::new($false))
            Move-Item -LiteralPath $temporary -Destination $Path -Force -ErrorAction Stop
        } finally {
            if(Test-Path -LiteralPath $temporary){ Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue }
        }
    }
    function Copy-RedockerSnapshotTree {
        param([Parameter(Mandatory)][string]$Source,[Parameter(Mandatory)][string]$Destination)
        if(-not (Test-Path -LiteralPath $Source -PathType Container)){ return 0 }
        $copied = 0
        New-Item -ItemType Directory -Force -Path $Destination | Out-Null
        foreach($item in @(Get-ChildItem -LiteralPath $Source -Force -Recurse -ErrorAction SilentlyContinue)){
            $relative = $item.FullName.Substring($Source.Length).TrimStart('\')
            if([string]::IsNullOrWhiteSpace($relative)){ continue }
            if($relative -match '(?i)(^|\\)(wsl|logs?|cache|tmp)(\\|$)' -or $item.Name -match '(?i)\.(vhdx|log|lock)$'){ continue }
            $target = Join-Path $Destination $relative
            if($item.PSIsContainer){
                New-Item -ItemType Directory -Force -Path $target | Out-Null
            } else {
                New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
                try {
                    Copy-Item -LiteralPath $item.FullName -Destination $target -Force -ErrorAction Stop
                    $copied++
                } catch {
                    Write-RedockerSafeLine ("snapshot skipped locked or unavailable file: {0}" -f $item.FullName) DarkYellow
                }
            }
        }
        return $copied
    }
    function Restore-RedockerSnapshotTree {
        param([Parameter(Mandatory)][string]$Snapshot,[Parameter(Mandatory)][string]$Destination)
        if(-not (Test-Path -LiteralPath $Snapshot -PathType Container)){ return 0 }
        $restored = 0
        foreach($item in @(Get-ChildItem -LiteralPath $Snapshot -Force -Recurse -File -ErrorAction Stop)){
            $relative = $item.FullName.Substring($Snapshot.Length).TrimStart('\')
            $target = Join-Path $Destination $relative
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
            Copy-Item -LiteralPath $item.FullName -Destination $target -Force -ErrorAction Stop
            $restored++
        }
        return $restored
    }
    function Save-RedockerSettingsSnapshot {
        param([Parameter(Mandatory)][string]$SnapshotRoot)
        New-Item -ItemType Directory -Force -Path $SnapshotRoot | Out-Null
        $fileSources = @(
            [pscustomobject]@{ Name = 'AppData-Docker'; Path = (Join-Path $env:APPDATA 'Docker') },
            [pscustomobject]@{ Name = 'AppData-DockerDesktop'; Path = (Join-Path $env:APPDATA 'Docker Desktop') },
            [pscustomobject]@{ Name = 'LocalAppData-Docker'; Path = (Join-Path $env:LOCALAPPDATA 'Docker') },
            [pscustomobject]@{ Name = 'User-Docker'; Path = (Join-Path $env:USERPROFILE '.docker') },
            [pscustomobject]@{ Name = 'ProgramData-DockerDesktop'; Path = (Join-Path $env:ProgramData 'DockerDesktop') }
        )
        $manifest = New-Object System.Collections.Generic.List[object]
        foreach($source in $fileSources){
            $destination = Join-Path $SnapshotRoot ('files\' + $source.Name)
            $count = Copy-RedockerSnapshotTree -Source $source.Path -Destination $destination
            if($count -gt 0){ $manifest.Add([pscustomobject]@{ Name = $source.Name; Source = $source.Path; Files = $count }) }
        }
        $environment = @{}
        foreach($item in @(Get-ChildItem Env: | Where-Object { $_.Name -match '^(?i)(DOCKER|COMPOSE|BUILDKIT)_' })){
            $environment[$item.Name] = [string]$item.Value
        }
        Save-RedockerSafeText -Path (Join-Path $SnapshotRoot 'environment.json') -Text ($environment | ConvertTo-Json -Depth 4)
        $reg = Join-Path $SnapshotRoot 'registry'
        New-Item -ItemType Directory -Force -Path $reg | Out-Null
        $regExe = Join-Path $env:SystemRoot 'System32\reg.exe'
        foreach($key in @('HKCU\Software\Docker Inc.','HKCU\Software\Docker Desktop','HKLM\SOFTWARE\Docker Inc.')){
            $safeName = ($key -replace '[\\:]','_') + '.reg'
            $target = Join-Path $reg $safeName
            $providerKey = if($key -like 'HKCU\*'){ $key -replace '^HKCU\\','HKCU:\' } else { $key -replace '^HKLM\\','HKLM:\' }
            if(Test-Path -LiteralPath $providerKey){
                try {
                    & $regExe export $key $target /y 2>$null | Out-Null
                    if(Test-Path -LiteralPath $target -PathType Leaf){ $manifest.Add([pscustomobject]@{ Name = $key; Registry = $target }) }
                } catch {
                    Write-RedockerSafeLine ("registry snapshot skipped {0}: {1}" -f $key,$_.Exception.Message) DarkYellow
                }
            }
        }
        Save-RedockerSafeText -Path (Join-Path $SnapshotRoot 'manifest.json') -Text (ConvertTo-Json -InputObject ($manifest.ToArray()) -Depth 5)
        Write-RedockerSafeLine ("settings snapshot saved: {0} ({1} file groups)" -f $SnapshotRoot,$manifest.Count) Green
        return $SnapshotRoot
    }
    function Get-RedockerManifestEntries {
        param([Parameter(Mandatory)][string]$ManifestPath)
        $raw = Get-Content -LiteralPath $ManifestPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        if($raw -is [System.Array]){ return @($raw) }
        if($raw.Name -is [System.Array]){
            $entries = New-Object System.Collections.Generic.List[object]
            for($index = 0; $index -lt $raw.Name.Count; $index++){
                $entry = [ordered]@{ Name = [string]$raw.Name[$index] }
                if($raw.Source -is [System.Array] -and $index -lt $raw.Source.Count){ $entry.Source = [string]$raw.Source[$index] }
                if($raw.Registry -is [System.Array] -and $index -lt $raw.Registry.Count){ $entry.Registry = [string]$raw.Registry[$index] }
                if($raw.Files -is [System.Array] -and $index -lt $raw.Files.Count){ $entry.Files = $raw.Files[$index] }
                [void]$entries.Add([pscustomobject]$entry)
            }
            return $entries.ToArray()
        }
        return @($raw)
    }
    function Restore-RedockerSettingsSnapshot {
        param([Parameter(Mandatory)][string]$SnapshotRoot)
        if(-not (Test-Path -LiteralPath $SnapshotRoot -PathType Container)){ throw "Docker settings snapshot not found: $SnapshotRoot" }
        $manifestPath = Join-Path $SnapshotRoot 'manifest.json'
        if(-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)){ throw "Docker settings snapshot manifest missing: $manifestPath" }
        $manifest = @(Get-RedockerManifestEntries -ManifestPath $manifestPath)
        $restored = 0
        foreach($entry in $manifest){
            $entryName = [string]$entry.Name
            $entrySource = [string]$entry.Source
            $entryRegistry = [string]$entry.Registry
            if(-not [string]::IsNullOrWhiteSpace($entrySource) -and $entryName -notmatch '\\'){
                $snapshot = Join-Path $SnapshotRoot ('files\' + $entryName)
                $restored += Restore-RedockerSnapshotTree -Snapshot $snapshot -Destination $entrySource
            } elseif(-not [string]::IsNullOrWhiteSpace($entryRegistry) -and (Test-Path -LiteralPath $entryRegistry -PathType Leaf)){
                $regExe = Join-Path $env:SystemRoot 'System32\reg.exe'
                & $regExe import $entryRegistry | Out-Null
                if($LASTEXITCODE -ne 0){ throw "Docker registry settings restore failed: $entryName" }
            }
        }
        $environmentPath = Join-Path $SnapshotRoot 'environment.json'
        if(Test-Path -LiteralPath $environmentPath -PathType Leaf){
            $environment = Get-Content -LiteralPath $environmentPath -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            foreach($property in $environment.PSObject.Properties){
                Set-Item -Path ('Env:{0}' -f $property.Name) -Value ([string]$property.Value)
                try { [Environment]::SetEnvironmentVariable($property.Name,[string]$property.Value,'User') } catch { }
            }
        }
        Write-RedockerSafeLine ("settings snapshot restored: {0} files" -f $restored) Green
        return $restored
    }
    function Get-RedockerSharedFileHash {
        param([Parameter(Mandatory)][string]$Path)
        $stream = $null
        $sha = $null
        try {
            $stream = [IO.File]::Open($Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete)
            $sha = [Security.Cryptography.SHA256]::Create()
            return ([BitConverter]::ToString($sha.ComputeHash($stream))).Replace('-','')
        } finally {
            if($sha){ $sha.Dispose() }
            if($stream){ $stream.Dispose() }
        }
    }
    function Test-RedockerSettingsSnapshot {
        param([Parameter(Mandatory)][string]$SnapshotRoot)
        $manifestPath = Join-Path $SnapshotRoot 'manifest.json'
        if(-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)){ return $false }
        $manifest = @(Get-RedockerManifestEntries -ManifestPath $manifestPath)
        foreach($entry in $manifest){
            $entryName = [string]$entry.Name
            $entrySource = [string]$entry.Source
            if(-not [string]::IsNullOrWhiteSpace($entrySource) -and $entryName -notmatch '\\'){
                $snapshot = Join-Path $SnapshotRoot ('files\' + $entryName)
                foreach($item in @(Get-ChildItem -LiteralPath $snapshot -Force -Recurse -File -ErrorAction Stop)){
