                    $target = Join-Path $entrySource $relative
                    if(-not (Test-Path -LiteralPath $target -PathType Leaf)){ return $false }
                    $sourceHash = $null
                    $targetHash = $null
                    for($attempt = 0; $attempt -lt 5 -and ($null -eq $sourceHash -or $null -eq $targetHash); $attempt++){
                        try { $sourceHash = Get-RedockerSharedFileHash -Path $item.FullName } catch { }
                        try { $targetHash = Get-RedockerSharedFileHash -Path $target } catch { }
                        if($null -eq $sourceHash -or $null -eq $targetHash){ Start-Sleep -Milliseconds 100 }
                    }
                    if($null -eq $sourceHash -or $null -eq $targetHash){ continue }
                    if($sourceHash -ne $targetHash){ return $false }
                }
            }
        }
        $criticalFiles = @(
            [pscustomobject]@{ Name = 'AppData-Docker'; Source = (Join-Path $env:APPDATA 'Docker'); Relative = 'settings-store.json' },
            [pscustomobject]@{ Name = 'User-Docker'; Source = (Join-Path $env:USERPROFILE '.docker'); Relative = 'daemon.json' },
            [pscustomobject]@{ Name = 'User-Docker'; Source = (Join-Path $env:USERPROFILE '.docker'); Relative = 'config.json' },
            [pscustomobject]@{ Name = 'ProgramData-DockerDesktop'; Source = (Join-Path $env:ProgramData 'DockerDesktop'); Relative = 'install-settings.json' }
        )
        foreach($critical in $criticalFiles){
            $snapshotFile = Join-Path $SnapshotRoot ('files\' + $critical.Name + '\' + $critical.Relative)
            $targetFile = Join-Path $critical.Source $critical.Relative
            if(Test-Path -LiteralPath $snapshotFile -PathType Leaf){
                if(-not (Test-Path -LiteralPath $targetFile -PathType Leaf)){ return $false }
                try {
                    if((Get-RedockerSharedFileHash -Path $snapshotFile) -ne (Get-RedockerSharedFileHash -Path $targetFile)){ return $false }
                } catch { return $false }
            }
        }
        return $true
    }

    function Set-RedockerKnownSettings {
        $dockerRoaming = Join-Path $env:APPDATA 'Docker'
        $dotDocker = Join-Path $env:USERPROFILE '.docker'
        New-Item -ItemType Directory -Force -Path $dockerRoaming | Out-Null
        New-Item -ItemType Directory -Force -Path $dotDocker | Out-Null
        $settingsStore = Join-Path $dockerRoaming 'settings-store.json'
        $settingsJson = Join-Path $dockerRoaming 'settings.json'
        $daemonJson = Join-Path $dotDocker 'daemon.json'
        $windowsDaemonJson = Join-Path $dotDocker 'windows-daemon.json'
        $settingsVersion = 45
        $full = $null
        if(Test-Path -LiteralPath $settingsStore){
            try {
                $full = Get-Content -LiteralPath $settingsStore -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                $currentVersion = 0
                try { $currentVersion = [int]$full.SettingsVersion } catch { }
                if($currentVersion -gt $settingsVersion){ $settingsVersion = $currentVersion }
            } catch { }
        }
        if(-not $full){
            $full = [pscustomobject][ordered]@{
                AutoStart = $false
                DisplayedOnboarding = $true
                EnableCLIHints = $true
                EnableDockerAI = $true
                EnableIntegrationWithDefaultWslDistro = $false
                FilesharingDirectories = @($env:USERPROFILE)
                InferenceCanUseGPUVariant = $true
                LicenseTermsVersion = 2
                MemoryMiB = 33792
                OpenUIOnStartupDisabled = $true
                SettingsVersion = $settingsVersion
                SwapMiB = 3072
                ThemeSource = 'dark'
                UseBackgroundIndexing = $false
                UseContainerdSnapshotter = $true
                UseLibkrun = $true
                UseResourceSaver = $false
                UseVirtualizationFramework = $false
                WslEngineEnabled = $false
            }
        }

        function Set-RedockerSetting {
            param([Parameter(Mandatory)]$Settings,[Parameter(Mandatory)][string]$Name,$Value)
            $property = $Settings.PSObject.Properties[$Name]
            if($property){ $property.Value = $Value } else { $Settings | Add-Member -NotePropertyName $Name -NotePropertyValue $Value }
        }
        Set-RedockerSetting -Settings $full -Name 'AutoStart' -Value $false
        Set-RedockerSetting -Settings $full -Name 'EnableIntegrationWithDefaultWslDistro' -Value $false
        Set-RedockerSetting -Settings $full -Name 'MemoryMiB' -Value 33792
        Set-RedockerSetting -Settings $full -Name 'OpenUIOnStartupDisabled' -Value $true
        Set-RedockerSetting -Settings $full -Name 'SettingsVersion' -Value $settingsVersion
        Set-RedockerSetting -Settings $full -Name 'SwapMiB' -Value 3072
        Set-RedockerSetting -Settings $full -Name 'UseBackgroundIndexing' -Value $false
        Set-RedockerSetting -Settings $full -Name 'UseContainerdSnapshotter' -Value $true
        Set-RedockerSetting -Settings $full -Name 'AllowBetaFeatures' -Value $true
        Set-RedockerSetting -Settings $full -Name 'UseLibkrun' -Value $true
        Set-RedockerSetting -Settings $full -Name 'UseResourceSaver' -Value $false
        Set-RedockerSetting -Settings $full -Name 'UseVirtualizationFramework' -Value $false
        Set-RedockerSetting -Settings $full -Name 'WslEngineEnabled' -Value $false
        $safeShares = @($full.FilesharingDirectories | Where-Object {
            -not [string]::IsNullOrWhiteSpace([string]$_) -and
            [string]$_ -notmatch '^[A-Za-z]:\\$' -and
            (Test-Path -LiteralPath ([string]$_) -PathType Container)
        } | Select-Object -Unique)
        if($safeShares.Count -eq 0){
            $safeShares = @(@($env:USERPROFILE,'C:\Temp','F:\study') | Where-Object {
                -not [string]::IsNullOrWhiteSpace([string]$_) -and
                (Test-Path -LiteralPath ([string]$_) -PathType Container)
            } | Select-Object -Unique)
        }
        Set-RedockerSetting -Settings $full -Name 'FilesharingDirectories' -Value $safeShares
        Save-RedockerSafeText -Path $settingsStore -Text ($full | ConvertTo-Json -Depth 5)
        Write-RedockerSafeLine ("applied Docker Desktop settings: Docker VMM, 33792 MiB memory, Resource Saver off, {0} explicit file shares, no startup" -f $safeShares.Count) Green
        if(Test-Path -LiteralPath $settingsJson -PathType Leaf){
            try {
                $desktop = Get-Content -LiteralPath $settingsJson -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
                Set-RedockerSetting -Settings $desktop -Name 'UseLibkrun' -Value $true
                Set-RedockerSetting -Settings $desktop -Name 'WslEngineEnabled' -Value $false
                Set-RedockerSetting -Settings $desktop -Name 'UseVirtualizationFramework' -Value $false
                Set-RedockerSetting -Settings $desktop -Name 'EnableIntegrationWithDefaultWslDistro' -Value $false
                Set-RedockerSetting -Settings $desktop -Name 'UseResourceSaver' -Value $false
                Set-RedockerSetting -Settings $desktop -Name 'AutoStart' -Value $false
                Save-RedockerSafeText -Path $settingsJson -Text ($desktop | ConvertTo-Json -Depth 5)
            } catch { Write-RedockerSafeLine ("legacy settings.json update skipped: {0}" -f $_.Exception.Message) DarkYellow }
        }
        $daemon = [ordered]@{
            builder = [ordered]@{ gc = [ordered]@{ defaultKeepStorage = '20GB'; enabled = $true } }
            experimental = $false
            'max-concurrent-downloads' = 10
            'max-concurrent-uploads' = 10
            'max-download-attempts' = 5
            features = [ordered]@{ buildkit = $true }
        }
        Save-RedockerSafeText -Path $daemonJson -Text ($daemon | ConvertTo-Json -Depth 5)
        Write-RedockerSafeLine 'applied daemon performance settings' Green
        if(-not (Test-Path -LiteralPath $windowsDaemonJson -PathType Leaf)){
            Save-RedockerSafeText -Path $windowsDaemonJson -Text "{`r`n}"
        }
        foreach($var in @('DOCKER_BUILDKIT','COMPOSE_DOCKER_CLI_BUILD')){
            try { [Environment]::SetEnvironmentVariable($var,'1','Machine') } catch { }
            Set-Item -Path ("Env:{0}" -f $var) -Value '1' -ErrorAction SilentlyContinue
        }
        try { [Environment]::SetEnvironmentVariable('BUILDKIT_PROGRESS','plain','Machine'); $env:BUILDKIT_PROGRESS='plain' } catch { }
    }

    if($SelfTest){
        [pscustomobject]@{
            Function = 'redocker'
            Mode = 'SnapshotPreservingReinstall'
            ConfigurationSource = 'Current Docker files, registry settings, contexts, credentials, and environment'
            UninstallOnly = [bool]$UninstallOnly
            Plan = [bool]$Plan
            Installer = 'winget uninstall followed by noninteractive exact Docker Desktop install with up to three attempts and stale-state cleanup'
            DataPreservation = 'Docker WSL virtual disks, ProgramData Docker config, and containerd state are never deleted'
            WingetPath = Resolve-RedockerSafeWingetPath
            DaemonReadinessBeforeReturn = $true
            SnapshotExcludes = @('Docker WSL virtual disks','logs','cache','temporary lock files')
        }
        return
    }
    $snapshotBase = if(Test-Path -LiteralPath 'F:\backup' -PathType Container){ 'F:\backup\Docker\redocker-snapshots' } else { Join-Path $env:USERPROFILE 'redocker-snapshots' }
    $snapshotRoot = Join-Path $snapshotBase (Get-Date -Format 'yyyyMMdd-HHmmss')
    if($Plan){
        [pscustomobject]@{
            Function = 'redocker'
            Mode = 'Plan'
            SnapshotRoot = $snapshotRoot
            Purge = -not $NoPurge
            UninstallOnly = [bool]$UninstallOnly
            Install = -not $SkipInstall -and -not $UninstallOnly
            ReadinessVerification = $true
        }
        return
    }
    if(-not (Test-RedockerSafeAdmin)){ throw 'redocker must run from an elevated Windows PowerShell 5 console.' }

    Write-Host "`n=== REDOCKER: FULL REINSTALL + CURRENT SETTINGS PRESERVATION ===" -ForegroundColor Magenta
    if(Test-RedockerSafePendingReboot){ Write-RedockerSafeLine 'a Windows reboot is pending; Docker Desktop install may fail or hang. Reboot first if this run fails.' Yellow }
    Stop-RedockerSafeDocker
    Save-RedockerSettingsSnapshot -SnapshotRoot $snapshotRoot | Out-Null
    if(-not $NoPurge){
        $purgePaths = @(
            [pscustomobject]@{ Path = (Join-Path ${env:ProgramFiles} 'Docker'); PreserveWslData = $false },
            [pscustomobject]@{ Path = (Join-Path ${env:ProgramFiles(x86)} 'Docker'); PreserveWslData = $false },
            [pscustomobject]@{ Path = "$env:ProgramData\DockerDesktop"; PreserveWslData = $false; PreserveVmData = $true },
            [pscustomobject]@{ Path = "$env:APPDATA\Docker"; PreserveWslData = $false },
            [pscustomobject]@{ Path = "$env:APPDATA\Docker Desktop"; PreserveWslData = $false },
            [pscustomobject]@{ Path = (Join-Path $env:USERPROFILE '.docker'); PreserveWslData = $false },
            [pscustomobject]@{ Path = "$env:LOCALAPPDATA\Docker"; PreserveWslData = $true; PreserveVmData = $true }
        )
        for($index = 0; $index -lt $purgePaths.Count; $index++){
            $path = $purgePaths[$index].Path
            Write-RedockerSafeProgress -Activity 'redocker: purging Docker data' -Status $path -PercentComplete ([int](($index / [Math]::Max(1,$purgePaths.Count)) * 100))
            Remove-RedockerSafePath -Path $path -PreserveWslData:$purgePaths[$index].PreserveWslData -PreserveVmData:$purgePaths[$index].PreserveVmData
        }
        Write-Progress -Id 847 -Activity 'redocker: purging Docker data' -Completed
        foreach($rk in @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Docker Desktop','HKLM:\SOFTWARE\Docker Inc.')){
            try { Remove-Item -LiteralPath $rk -Recurse -Force -ErrorAction SilentlyContinue } catch { }
        }
    }

    if($UninstallOnly){
        if(-not $SkipInstall){
            $winget = Resolve-RedockerSafeWingetPath
            if(-not $winget){ throw 'winget is required to uninstall Docker Desktop and was not found.' }
            $uninstallCode = Invoke-RedockerSafeNative -Label 'winget uninstall Docker Desktop' -FilePath $winget -ArgumentList @('uninstall','--id','Docker.DockerDesktop','-e','--source','winget','--accept-source-agreements','--silent','--disable-interactivity') -TimeoutSeconds 300
            if($uninstallCode -ne 0){ throw ("Docker Desktop uninstall failed with exit {0}." -f $uninstallCode) }
        }
        Write-RedockerSafeLine ("uninstall-only complete; settings snapshot retained at {0}" -f $snapshotRoot) Green
        return
    }

    $desktopExe = Join-Path ${env:ProgramFiles} 'Docker\Docker\Docker Desktop.exe'
    $dockerExe = Join-Path ${env:ProgramFiles} 'Docker\Docker\resources\bin\docker.exe'
    if(-not $SkipInstall){
        $winget = Resolve-RedockerSafeWingetPath
        if(-not $winget){ throw 'winget is required to reinstall Docker Desktop and was not found.' }
        $uninstallCode = Invoke-RedockerSafeNative -Label 'winget uninstall Docker Desktop' -FilePath $winget -ArgumentList @('uninstall','--id','Docker.DockerDesktop','-e','--source','winget','--accept-source-agreements','--silent','--disable-interactivity') -TimeoutSeconds 300
        if($uninstallCode -ne 0){ Write-RedockerSafeLine ("winget uninstall exit={0}; continuing after filesystem/registry purge" -f $uninstallCode) Yellow }
        $installArgs = @('install','--id','Docker.DockerDesktop','-e','--source','winget','--accept-package-agreements','--accept-source-agreements','--silent','--force','--disable-interactivity')
        $maxAttempts = 3
        $installed = $false
        $lastCode = -1
        for($attempt = 1; $attempt -le $maxAttempts; $attempt++){
            Stop-RedockerSafeDocker
            if($attempt -gt 1){
                Write-RedockerSafeLine ("install attempt {0}: clearing stale install state from previous attempt" -f $attempt) Yellow
                Start-Sleep -Seconds 6
                try { Remove-Item -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\Docker Desktop' -Recurse -Force -ErrorAction SilentlyContinue } catch { }
                Remove-RedockerSafePath -Path (Join-Path ${env:ProgramFiles} 'Docker')
            }
            $label = if($attempt -eq 1){ 'winget install Docker Desktop' } else { 'winget install Docker Desktop retry' }
            $lastCode = Invoke-RedockerSafeNative -Label $label -FilePath $winget -ArgumentList $installArgs -TimeoutSeconds 1200
            if($lastCode -eq 124){
                Write-RedockerSafeLine 'winget install was stopped on timeout; killing any lingering installer process before next attempt' Yellow
                Stop-RedockerSafeDocker
                Start-Sleep -Seconds 3
            }
            if($lastCode -eq -6 -or $lastCode -eq 4294967290){
                Write-RedockerSafeLine 'installer reported 0xFFFFFFFA (-6): usually a leftover installer instance or stale install state; deep cleanup will run before the next attempt' Yellow
            }
            $found = Wait-RedockerSafeDockerFiles -TimeoutSeconds $(if($lastCode -eq 0){ 180 } else { 45 })
            $desktopExe = $found.DesktopExe
            $dockerExe = $found.DockerExe
            if($lastCode -eq 0 -and $desktopExe -and $dockerExe -and (Test-Path -LiteralPath $desktopExe) -and (Test-Path -LiteralPath $dockerExe)){ $installed = $true; break }
        }
        if(-not $installed){ throw ("Docker Desktop reinstall failed after {0} attempts (last winget exit {1}). See installer logs under %TEMP%\Docker Installer*.log." -f $maxAttempts,$lastCode) }
        if(-not $desktopExe -or -not (Test-Path -LiteralPath $desktopExe)){ throw 'Docker Desktop executable missing after reinstall.' }
        if(-not $dockerExe -or -not (Test-Path -LiteralPath $dockerExe)){ throw 'Docker CLI executable missing after reinstall.' }
        Write-RedockerSafeLine ("installed executables: desktop={0}; cli={1}" -f $desktopExe,$dockerExe) Green
    }

    Write-RedockerSafeProgress -Activity 'redocker: restoring current configuration' -Status 'restoring Docker Desktop settings, credentials, contexts, and environment' -PercentComplete 75
    Restore-RedockerSettingsSnapshot -SnapshotRoot $snapshotRoot | Out-Null
    if(-not (Test-RedockerSettingsSnapshot -SnapshotRoot $snapshotRoot)){ throw 'Docker settings restoration verification failed.' }
    Write-Progress -Id 847 -Activity 'redocker: restoring recovered configuration' -Completed

    Set-RedockerKnownSettings

    if(Test-Path -LiteralPath $desktopExe){
        try { Start-Process -FilePath $desktopExe -ArgumentList @('--minimized') -WindowStyle Hidden | Out-Null; Write-RedockerSafeLine 'Docker Desktop launched' Green } catch { Write-RedockerSafeLine ("Docker Desktop launch failed: {0}" -f $_.Exception.Message) Yellow }
    }
    if(-not (Wait-RedockerSafeDockerReady -DockerExe $dockerExe -TimeoutSeconds 180)){
        throw 'Docker daemon was not ready after redocker reinstall/launch; returning failure instead of false success.'
    }
    Write-RedockerSafeLine 'Docker daemon ready after reinstall/launch' Green
    $elapsed = [Math]::Round(((Get-Date)-$started).TotalSeconds,2)
    Write-Progress -Id 847 -Activity 'redocker' -Completed
    Write-RedockerSafeLine ("complete in {0}s; current settings snapshot restored and verified at {1}; returning to shell now" -f $elapsed,$snapshotRoot) Green
}

if ($MyInvocation.InvocationName -ne '.') {
    & 'Invoke-HermesDockerPreserveRedocker' @args
}
